import re
lines = open('/tmp/fulllog.txt', encoding='utf-8').read().split('\n')
commits = []
cur = None
for l in lines:
    if l.startswith('COMMIT '):
        if cur: commits.append(cur)
        parts = l[7:].split('|')
        h = parts[0]; date=parts[1]; subj = parts[2]
        m = re.match(r'\[(.*?)\]', subj)
        author = m.group(1) if m else 'NONE'
        cur = {'h':h,'date':date,'subj':subj,'author':author,'files':[]}
    elif l.strip():
        cur['files'].append(l.strip())
if cur: commits.append(cur)
print('total commits', len(commits))

def zone_ok(author, f):
    if author == 'CEO':
        return True  # ceo can touch shared files, but check src/tools compute sh not really ceo zone either; be lenient
    if author == 'Исследователь':
        if f.startswith('src/') or f.startswith('Cargo.'):
            return False
        if f.startswith('tools/compute/') and f.endswith('.sh'):
            return False
        if f in ('CLAUDE.md','docs/plan/SETTLED.md','.memory/index.md') :
            return False
        if f.startswith('.claude/hooks/'):
            return False
        if f.startswith('.claude/skills/'):
            return False
        return True
    if author == 'Инженер':
        if f.startswith('docs/research/') and not f.startswith('docs/research/reviews/'):
            return False
        if f in ('CLAUDE.md','docs/plan/SETTLED.md','.memory/index.md'):
            return False
        if f.startswith('.claude/hooks/'):
            return False
        if f.startswith('.claude/skills/'):
            return False
        return True
    if author == 'Судья':
        if f.startswith('docs/research/reviews/'):
            return True
        if f.startswith('.claude/roles/notes/judge') or f.startswith('.claude/roles/journal/'):
            return True
        if f == '.claude/roles/TASKS.md':
            return True  # own line edits allowed
        if f in ('CLAUDE.md','docs/plan/SETTLED.md','.memory/index.md'):
            return False
        if f.startswith('.claude/skills/') or f.startswith('.claude/hooks/'):
            return False
        if f.startswith('src/') or f.startswith('tools/'):
            return False
        if f.startswith('docs/') and not f.startswith('docs/research/reviews/'):
            return False
        return None  # uncertain, flag
    return None

violations = []
for c in commits:
    a = c['author']
    for f in c['files']:
        ok = zone_ok(a, f)
        if ok is False:
            violations.append((c['h'], c['date'], a, f, c['subj']))
        elif ok is None and a=='Судья':
            violations.append((c['h'], c['date'], a, f, c['subj']+' [UNCERTAIN]'))

for v in violations:
    print(v)
print('count', len(violations))
"

